"Все грани собраны. Финал — через {0}: во всех Разломах мира будет ждать Кощей.":"すべての面がそろいました。決戦は{0}後です。世界中のすべての裂け目でコシチェイが待ち構えます。",
"Открылась новая мифология — «{0}». Начался сезон {1}.":"新しい神話「{0}」が開かれました。シーズン{1}が始まりました。",
"Какой мир открылся — Орден узнает с обновлением игры. Начался сезон {0}.":"どの世界が開いたのかは、ゲームのアップデートで捕り手団に知らされます。シーズン{0}が始まりました。",
