"Мифология сезона {0}. Когда Орден соберёт все {1} граней, Кощей придёт за камнем и расколет его — и из трещины выйдет новый мир.":"シーズン{0}の神話。捕り手団が{1}面すべてをそろえると、コシチェイが石を奪いに来て砕きます。そして割れ目から新しい世界が現れます。",
"Множитель Ордена ×{0} — активных Ловчих {1}+ уровня: {2}":"捕り手団の倍率 ×{0} — レベル{1}以上の活動中の捕り手：{2}人",
"Чем больше Ловчих {0}+ уровня играли за последние {1} дней, тем дороже новые грани: +{2}% за каждого, но не больше чем вдвое дороже прошлой грани. Цена грани фиксируется, когда грань открывается, и дальше не меняется. «≈» — ориентир для граней, что ещё не открылись.":"最近{1}日間にプレイしたレベル{0}以上の捕り手が多いほど、新しい面は高くなります。1人につき+{2}%ですが、前の面の2倍までです。面の価格は開いたときに決まり、その後は変わりません。「≈」はまだ開いていない面の目安です。",
