"В сезоне {0} у камня {1} граней — по одной на каждую мифологию. Новая мифология сезона — последняя грань. Всего за сезон — {2} осколков.":"シーズン{0}の石は{1}面で、神話ごとに一面ずつです。シーズンの新しい神話は最後の面です。シーズン全体で欠片{2}個が必要です。",
"Награда за сезон":"シーズン報酬",
