"Каждый осколок Алатыря, найденный любым Ловчим, — в разломах и у хранителей-старейшин Святилищ, — ложится в общий камень Ордена. Собрана грань — дорога в её мир распутана: {0} дня духи этой мифологии встречаются в {1} раза чаще, у всех Ловчих разом. Собраны все грани сезона — приходит Кощей: {2} дней он ждёт во всех Разломах мира, а потом раскалывает камень. Из трещины выходит новая мифология, начинается новый сезон — и в Лиге тоже. В новом сезоне у камня на одну грань больше.":"どの捕り手が見つけたアラトゥイリの欠片も、裂け目で得たものも聖所の長老守護者から得たものも、すべて捕り手団の共有の石に加わります。一面がそろうと、その世界への道のもつれがほどけます。{0}日間、その神話の精霊がすべての捕り手のもとで{1}倍よく現れます。シーズンのすべての面がそろうとコシチェイがやって来ます。{2}日間、世界中のすべての裂け目で待ち構え、そのあと石を砕きます。割れ目から新しい神話が現れ、新しいシーズンが始まります。リーグも同じです。新しいシーズンの石は面がひとつ増えます。",
