"Европа":"ヨーロッパ",
"Здесь сходятся старые дороги Нави, Олимпа, Асгарда и холмов сидов — от Москвы до Дублина.":"ナヴィ、オリュンポス、アースガルズ、シーの丘へ続く古い道がここで交わります。モスクワからダブリンまで。",
"Азия":"アジア",
"От Уральских гор до Тихого океана. Отсюда родом небесные драконы Китая, а Сибирь и Средняя Азия — края славянских духов.":"ウラル山脈から太平洋まで。中国の天の竜はここから生まれ、シベリアと中央アジアはスラヴの精霊の地です。",
"Африка":"アフリカ",
"Здесь, у Нила, стоят врата Дуата — родины египетских богов и духов пустыни.":"ここナイル河畔には、エジプトの神々と砂漠の精霊のふるさと、ドゥアトの門が立っています。",
"Северная Америка":"北アメリカ",
"Земля пернатых змеев: из долины Мехико вышли ацтекские боги и духи.":"羽毛の蛇の地。アステカの神々と精霊はメキシコ盆地から現れました。",
"Южная Америка":"南アメリカ",
"Сельва, Анды и Амазонка. Ацтекские духи разлетелись и сюда — до самой Огненной Земли.":"密林とアンデス山脈とアマゾン川。アステカの精霊はここまで散らばりました。フエゴ島の果てまで。",
"Австралия и Океания":"オーストラリアとオセアニア",
"Своих мифологий у Ордена здесь пока нет: сюда забредают китайские духи из соседней Юго-Восточной Азии.":"ここにはまだ団の知る土地の神話がありません。となりの東南アジアから中国の精霊がやって来ます。",
"Антарктида":"南極大陸",
"Здесь только пингвины и ледяные духи. Врата сюда не открываются — слишком холодно даже для Ловчих.":"ここにいるのはペンギンと氷の精霊だけです。門はここへは開きません。捕り手にも寒すぎるのです。",
"Миров духов всегда было много — у каждого народа свой: Навь у славян, царство Аида у греков, Асгард у скандинавов, холмы сидов у кельтов, Дуат у египтян, Небеса у китайцев, Миктлан у ацтеков. На местах их держал <b>Алатырь</b> — бел-горюч камень в середине всех миров. Каждые врата вели в свою землю, и духи не путали дорог.":"精霊の世界は昔からたくさんあり、民ごとにそれぞれの世界がありました。スラヴのナヴィ、ギリシャのハデスの国、北欧のアスガルド、ケルトの妖精の丘、エジプトのドゥアト、中国の天界、アステカのミクトラン。それらを所定の場所につなぎとめていたのが、すべての世界の真ん中にある燃える白い石<b>アラトゥイリ</b>です。どの門も自分の土地へ通じていて、精霊たちが道を間違えることはありませんでした。",
"Однажды осенней ночью Кощей Бессмертный решил спрятать свою смерть понадёжнее — прямо в сердце Алатыря. Камень треснул и раскололся. Все врата распахнулись разом, дороги между мирами спутались в клубок, и духи и боги семи мифологий высыпали в наш мир — каждый в своих краях. Эту ночь назвали <b>Перепутицей</b>. Кощей уверяет, что камень треснул сам, но Локи и Сунь Укун при этих словах почему-то хихикают.":"ある秋の夜、不死身のコシチェイは自分の死をもっと安全な場所に隠そうと、アラトゥイリの心臓そのものに押しこみました。石はひび割れ、真っ二つに。すべての門がいっせいに開き、世界と世界をつなぐ道は毛糸玉のようにもつれ、7つの神話の精霊と神々が私たちの世界へこぼれ出て、それぞれ自分の土地に住みついたのです。この夜は<b>大もつれ</b>と呼ばれています。コシチェイは「石が勝手に割れたんだ」と言い張りますが、そのたびにロキと孫悟空がなぜかくすくす笑っています。",
"Теперь Гиппокамп плещется в фонтанах Рима, Леший гуляет по подмосковным паркам, а Ниссе греет котов в подъездах Осло: каждый дух живёт у себя на родине, и за чужими приходится шагать через Врата. Разломы — трещины от расколотого камня — открываются в каждом городе, а боги ставят святилища у себя на родине: Святилища — на Руси, Храмы — в Греции, Пагоды — в Китае, Пирамиды — в Америке. Город рождает и своих, новых духов: Вайфайку, Трамвайника, Фонарника.":"今ではヒッポカンポスがローマの噴水で水しぶきを上げ、レーシーがモスクワ郊外の公園を散歩し、ニッセがオスロのアパートの階段で猫たちを温めています。精霊はみな自分の故郷に住んでいて、よその精霊に会うには門をくぐらなければなりません。割れた石が残したひび――裂け目はどの街にも開き、神々はそれぞれの故郷に聖所を建てます。聖所はルーシに、神殿はギリシャに、塔は中国に、ピラミッドはアメリカに。街は自分だけの新しい精霊、ワイファイカ、トラムヴァイニク、フォナルニクも生み出しています。",
"Первыми с гостями поладили не учёные, а бабушки со своими оберегами: оказалось, оберег, сделанный с заботой, успокаивает любого духа, откуда бы тот ни был. Так появился <b>Орден Оберега</b> — союз Ловчих всех земель. Твоя задача — находить духов, ловить их оберегами, черпать силу из источников, закрывать разломы и собирать осколки Алатыря. Кто знает — может, однажды их хватит, чтобы распутать дороги домой.":"来訪者たちと最初に仲よくなったのは、学者ではなく、お守りを手にしたおばあちゃんたちでした。心をこめて作ったお守りは、どこから来た精霊でも落ち着かせるとわかったのです。こうして、あらゆる土地の捕り手の集まり<b>お守りの捕り手団</b>が生まれました。あなたの役目は、精霊を見つけてお守りで捕まえ、泉源から力をくみ、裂け目を閉じ、アラトゥイリの欠片を集めることです。いつか欠片がそろえば、もつれた家路をほどけるかもしれません。",
