"Награда за сегодня уже получена — сейчас это тренировка (+100 опыта за победу).":"今日の報酬は受け取り済みです。今は練習試合です（勝利で経験値+100）。",
"Награда за первую победу за день: 800 опыта, ✦ 500, обереги и мёд, +1 ★ дружбы.":"その日最初の勝利の報酬：経験値800、✦ 500、お守りとハチミツ、フレンド度+1 ★。",
