"Тапай — быстрая атака, она копит энергию.<br>Полная шкала — жми «Приём». Щиты берегут от приёмов хранителя.":"タップで速攻。エネルギーがたまります。<br>ゲージが満タンになったら「技」を押そう。シールドで守護者の技を防げます。",
