"Сервер не подтвердил этот бой. Проверь интернет и попробуй снова.":"サーバーがこのバトルを確認できませんでした。通信環境を確認して、もう一度お試しください。",
"Защитники «{0}» отступили — Святилище «{1}» свободно!":"「{0}」の守り手が退却しました。聖所「{1}」は解放されました！",
"Победа засчитана, но пока шёл бой, в Святилище сменились защитники.":"勝利は認められましたが、バトル中に聖所の守り手が入れ替わりました。",
"«Достойно, Ловчий», — {0} склоняет голову. Святилище «{1}» освящено тобой до конца дня.":"「見事だ、捕り手よ」{0}が頭を下げます。聖所「{1}」は今日の終わりまであなたが清めました。",
"Победа!":"勝利！",
"Поставь своего защитника — и Святилище перейдёт твоему клану.":"守り手を置けば、聖所はあなたのクランのものになります。",
"Поражение":"敗北",
"«Приходи, когда окрепнешь», — говорит {0}. Попробуй другую команду: смотри на стихии хранителя и береги щиты для его приёмов.":"「強くなってから来るがよい」と{0}が言います。別のチームで挑戦してみましょう。守護者の属性に注目して、シールドは守護者の技のためにとっておきましょう。",
"Хорошая тренировка! Награда за поединок с {0} сегодня уже получена.":"いい練習になりました！{0}との決闘の報酬は今日はもう受け取っています。",
"{0} жмёт тебе руку: «Честный бой!» Дружба крепнет.":"{0}が握手を求めてきました。「正々堂々のいい勝負だった！」フレンド度がアップ。",
"<b>+1 ★</b> дружбы":"フレンド度 <b>+1 ★</b>",
"Духи {0} оказались сильнее. Подбери команду против их стихий и попробуй снова — поединки с другом не ограничены.":"{0}の精霊のほうが強かったようです。相手の属性に合わせてチームを組み直し、もう一度挑戦しましょう。フレンドとの決闘は何度でもできます。",
"Источник освобождён!":"泉源を解放しました！",
"Прислужник растворился в тумане. Один из его духов — омрачённый {0} — остался рядом. Его ещё можно спасти!":"手下は霧の中に消えました。その精霊の1体、闇堕ちした{0}がそばに残っています。まだ救えます！",
"Спасти духа":"精霊を救う",
"Навь сильнее… пока":"ナヴィのほうが強い…今のところは",
"«{0}» — смеётся прислужник. Возьми духов, сильных против стихии «{1}», и возвращайся.":"「{0}」と手下があざ笑います。「{1}」属性に強い精霊を連れて、また来ましょう。",
"Сдаться?":"降参しますか？",
