"Попади в кольцо, когда оно маленькое!":"サークルが小さいときに当てよう！",
"Сияющий дух!":"色違いの精霊！",
"<b>Зажми оберег и смахни вверх</b>, прямо к духу.<br>Чем быстрее свайп — тем дальше бросок.":"<b>お守りを押さえて上にスワイプ</b>、精霊をめがけて。<br>スワイプが速いほど遠くへ飛びます。",
"Есть только «{0}»":"「{0}」しかありません",
"Нет оберегов":"お守りがありません",
"Дух уже лакомится мёдом":"精霊はもうハチミツを味わっています",
"Мёда нет. Его можно найти у источников.":"ハチミツがありません。泉源で見つかります。",
"Дух ест мёд и успокаивается":"精霊がハチミツを食べて落ち着きました",
