"Друг у разлома нажал «Позвать друзей» и прислал код из 5 символов? Введи его — и в бой вместе, где бы ты ни был.":"裂け目にいるフレンドが「フレンドを誘う」を押して5文字のコードを送ってきましたか？コードを入力すれば、どこにいても一緒にバトルできます。",
