"Духи скрыты":"精霊は非公開",
"Ловчий ещё не выбрал спутника.":"この捕り手はまだ相棒を選んでいません。",
"Сильнейшие духи — для поединка":"最強の精霊：決闘用",
"{0} теперь твой друг!":"{0}とフレンドになりました！",
"Заявка отправлена: когда {0} добавит тебя в ответ, вы станете друзьями":"申請を送りました：{0}が追加し返してくれたら、フレンドになります",
