"Команда на бой":"出場チーム",
"Соперник — Ловчий с рейтингом ±{0} от твоего, а если такого нет — Ловчий Ордена. Рейтинг зависит от силы соперника · опыт — за первые {1} боёв дня":"対戦相手は、レーティングがあなたと±{0}以内の捕り手。いなければ捕り手団の捕り手が相手になります。レーティングは相手の強さで変わります · 経験値は1日の最初の{1}戦まで",
