"от {0}":"{0}以上",
"начало пути":"スタート地点",
"Получено в этом сезоне":"今シーズン受け取り済み",
"Рейтинг зависит от соперника: победа над сильным даёт много, над слабым — мало; поражение от слабого стоит дороже. В твоей лиге победа над равным — +{0}, поражение — −{1}; чем выше лига, тем медленнее подъём. Из лиги можно выпасть. Награду за лигу дают один раз за сезон. В начале нового сезона рейтинг сверх {2} срезается наполовину, а за высшую лигу прошлого сезона Орден дарит сундук. В лигах «{3}», «{4}» и «{5}» — ещё и амулет.":"レートは相手次第。強い相手に勝てば大きく、弱い相手なら少しだけ。弱い相手に負けると大きく減ります。あなたのリーグで互角の相手に勝つと+{0}、負けると−{1}。上のリーグほど上がりにくくなります。リーグから落ちることもあります。リーグの報酬はシーズンに1回。新シーズン開始時に{2}を超えた分のレートが半分になり、前シーズンの最上位リーグには団から宝箱が贈られます。リーグ「{3}」「{4}」「{5}」ではアミュレットも。",
"<b>{0}-е место</b> из {1} в сезоне":"今シーズン{1}人中<b>{0}位</b>",
"Сыграй бой, чтобы попасть в таблицу":"1戦すると表に載ります",
"Карточка откроется после обновления сервера":"サーバーの更新後にカードが開けるようになります",
"Неизвестный ход":"不明な操作",
