"Неверный приём":"無効な技",
"Этого духа не выпустить":"この精霊は出せません",
"Бросай оберег, когда кольцо сжимается: «Отлично!» даёт больше опыта и шанс поимки.":"サークルが縮んでいるときにお守りを投げよう。「グレート！」で経験値も捕獲率もアップ。",
"Источники наполняются снова через несколько минут — прогулка по кругу приносит припасы.":"泉源は数分でまた満ちます。ぐるっと散歩すれば道具が集まります。",
"Спутник ходит с тобой и находит эссенцию своего семейства.":"相棒は一緒に歩いて、自分の系統のエッセンスを見つけてくれます。",
"В Лиге дерутся живые Ловчие: победа над сильным соперником даёт больше рейтинга, чем над слабым.":"リーグで戦うのは本物の捕り手。強い相手に勝つほど、弱い相手より多くのレートがもらえます。",
"Разломы открываются у Святилищ каждый час: собери команду из трёх духов.":"裂け目は毎時聖所のそばに開きます。3体の精霊でチームを組みましょう。",
"Сияющие духи редки — их выдают искры вокруг.":"色違いの精霊はめったにいません。まわりに舞う火の粉が目印です。",
"Коконы греются шагами: одновременно можно греть три.":"繭は歩いて温めます。同時に温められるのは3つまで。",
"Ходи джойстиком: лёгкий наклон — шаг, до упора — бег. Километры для коконов считаются так же.":"ジョイスティックで歩きましょう。軽く倒すと歩き、いっぱいに倒すと走ります。繭の距離も同じようにカウントされます。",
"Атлас мира переносит в любой уголок Земли раз в полчаса, а Врата Перепутицы — сразу.":"世界アトラスなら30分に1回、地球のどこへでも行けます。「大もつれの門」ならすぐです。",
"Задания дня обновляются в полночь, а за все три ждёт Сундук дня.":"今日の任務は0時に更新。3つすべて達成するとデイリー宝箱がもらえます。",
"Поставь защитника в Святилище своего клана — он принесёт искры.":"自分のクランの聖所に守り手を置けば、火の粉を持ってきてくれます。",
"Погода усиливает духов своей стихии: в дождь чаще встречаются водные.":"天気は同じ属性の精霊を強くします。雨の日は水の精霊がよく出ます。",
